(function(){
  function fmt(v){
    if(v===null) return 'null';
    if(typeof v==='boolean') return v?'true':'false';
    if(typeof v==='number') return String(v);
    if(typeof v==='string') return JSON.stringify(v);
    if(Array.isArray(v)) return JSON.stringify(v);
    if(typeof v==='object') return '{}';
    return JSON.stringify(v);
  }
  function walk(prefix, val, out){
    if(val!==null && typeof val==='object' && !Array.isArray(val)){
      var keys=Object.keys(val);
      if(keys.length===0){ out.push(prefix+' = {};'); return; }
      keys.forEach(function(k){ walk(prefix+'.'+k, val[k], out); });
    } else if(Array.isArray(val)){
      if(val.length===0){ out.push(prefix+' = [];'); return; }
      val.forEach(function(item, i){ walk(prefix+'['+i+']', item, out); });
    } else {
      out.push(prefix+' = '+fmt(val)+';');
    }
  }
  function gron(json){
    var obj;
    try{ obj=JSON.parse(json); }catch(e){ return {error:'JSON 解析失败: '+e.message}; }
    var out=[];
    walk('json', obj, out);
    return {value: out.join('\n')};
  }
  var API={gron:gron, walk:walk, fmt:fmt};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__GronForge__=API;
})();
